DONE = "[DONE]"
_FINISH = ("length", "stop")


def _fail(reason):
    return {"success": False, "reason": reason}


def _is_count(value):
    return type(value) is int and value >= 0


def evaluate(status, frames, requested_tokens):
    if type(status) is not int or status != 200:
        return _fail("http_error")
    if not isinstance(frames, (list, tuple)):
        return _fail("malformed_frame")

    n = len(frames)
    terminal = None
    done_seen = False

    for i, frame in enumerate(frames):
        if isinstance(frame, str):
            if frame == DONE:
                if done_seen or i != n - 1:
                    return _fail("malformed_frame")
                done_seen = True
                continue
            return _fail("malformed_frame")
        if not isinstance(frame, dict):
            return _fail("malformed_frame")
        if "error" in frame:
            return _fail("stream_error")
        keys = set(frame.keys())
        if keys == {"content"}:
            if not isinstance(frame["content"], str):
                return _fail("malformed_frame")
            if terminal is not None:
                return _fail("malformed_frame")
            continue
        if keys == {"finish_reason", "completion_tokens"}:
            reason = frame["finish_reason"]
            count = frame["completion_tokens"]
            if not isinstance(reason, str) or reason not in _FINISH:
                return _fail("malformed_frame")
            if not _is_count(count):
                return _fail("malformed_frame")
            if terminal is not None:
                return _fail("malformed_frame")
            terminal = (reason, count)
            continue
        return _fail("malformed_frame")

    if terminal is None:
        return _fail("missing_terminal")

    reason, count = terminal
    if type(requested_tokens) is not int or requested_tokens <= 0:
        return _fail("token_mismatch")
    if reason == "length":
        if count != requested_tokens:
            return _fail("token_mismatch")
    else:
        if count > requested_tokens:
            return _fail("token_mismatch")
    return {"success": True, "reason": reason}

_DONE = "[DONE]"
_REASONS = ("length", "stop")


def _fail(reason):
    return {"success": False, "reason": reason}


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def evaluate(status, frames, requested_tokens):
    if not _is_int(status) or status != 200:
        return _fail("http_error")

    if not isinstance(frames, (list, tuple)):
        return _fail("malformed_frame")

    terminal = None
    last_index = len(frames) - 1

    for index, frame in enumerate(frames):
        if isinstance(frame, str):
            if frame == _DONE and index == last_index:
                # Single optional final DONE; not a terminal by itself.
                continue
            return _fail("malformed_frame")

        if not isinstance(frame, dict):
            return _fail("malformed_frame")

        if "error" in frame:
            return _fail("stream_error")

        keys = set(frame.keys())

        if keys == {"content"}:
            if not isinstance(frame["content"], str):
                return _fail("malformed_frame")
            if terminal is not None:
                return _fail("malformed_frame")
            continue

        if keys == {"finish_reason", "completion_tokens"}:
            reason = frame["finish_reason"]
            count = frame["completion_tokens"]
            if not isinstance(reason, str) or reason not in _REASONS:
                return _fail("malformed_frame")
            if not _is_int(count) or count < 0:
                return _fail("malformed_frame")
            if terminal is not None:
                return _fail("malformed_frame")
            terminal = (reason, count)
            continue

        return _fail("malformed_frame")

    if terminal is None:
        return _fail("missing_terminal")

    reason, count = terminal

    if not _is_int(requested_tokens) or requested_tokens <= 0:
        return _fail("token_mismatch")

    if reason == "length":
        if count != requested_tokens:
            return _fail("token_mismatch")
        return {"success": True, "reason": "length"}

    if count > requested_tokens:
        return _fail("token_mismatch")
    return {"success": True, "reason": "stop"}
